-- Query-plan and FK index hardening for the November 2026 What If Mission foundation.
alter policy ifund_missions_owner_read on public.ifund_missions using (owner_id=(select auth.uid()) and (select public.ifund_current_account_is_active()) and coalesce(((select auth.jwt())->>'is_anonymous')::boolean,false)=false);
