alter policy ifund_missions_owner_add on public.ifund_missions with check (owner_id=(select auth.uid()) and (select public.ifund_current_account_is_active()) and coalesce(((select auth.jwt())->>'is_anonymous')::boolean,false)=false and (select public.ifund_current_user_has_current_terms()));
